async (page) => {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  const assert = (value, message) => { if (!value) throw new Error(message); };
  await page.context().grantPermissions(['clipboard-read', 'clipboard-write']);
  await page.setViewportSize({ width: 1440, height: 1000 });
  const results = [];
  for (const [index, name] of ['逐步引导', '双栏工作台', '紧凑清单'].entries()) {
    await page.getByRole('button', { name, exact: true }).click();
    await page.getByRole('textbox', { name: '项目空间名称' }).fill('   ');
    await page.getByRole('button', { name: '创建项目空间', exact: true }).click();
    assert(await page.getByRole('textbox', { name: '项目空间名称' }).isVisible(), '空名不应创建');
    await page.getByRole('textbox', { name: '项目空间名称' }).fill('品牌官网');
    await page.getByRole('button', { name: '创建项目空间', exact: true }).click();
    const switcher = page.getByRole('combobox', { name: '切换项目空间' }).first();
    const id = await switcher.inputValue();
    await page.getByRole('button', { name: '复制命令', exact: true }).click();
    const init = await page.evaluate(() => navigator.clipboard.readText());
    assert(init.includes(' init ') && init.includes(id), '初始化未使用空间编号');
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.screenshot({ path: `output/playwright/new-home-${index + 1}.png`, fullPage: true });
    await page.getByRole('combobox', { name: '模拟检测结果' }).selectOption('expired');
    await page.getByRole('button', { name: '重新生成初始化命令' }).click();
    await page.getByRole('button', { name: '模拟初始化完成' }).click();
    await page.getByRole('button', { name: '进入设计体系' }).click();
    await page.getByRole('radio', { name: /使用产品主题与阶梯/ }).check();
    assert(await page.getByRole('button', { name: '生成待应用版本' }).isDisabled(), '缺失映射应阻止生成');
    await page.getByLabel('活动强调色如何处理').selectOption('primary');
    await page.getByRole('button', { name: '生成待应用版本' }).click();
    await page.getByRole('slider', { name: '圆角阶梯' }).fill('16');
    assert(await page.getByText(/草稿已变化/).isVisible(), '旧版本应保持不变');
    await page.getByRole('button', { name: '复制命令', exact: true }).click();
    assert((await page.evaluate(() => navigator.clipboard.readText())).includes('--version demo-v1'), '版本命令不正确');
    await page.getByRole('button', { name: '生成新版本' }).click();
    await page.getByRole('button', { name: '模拟本地文件冲突' }).click();
    assert(await page.getByText(/检测到本地文件变化，已停止写入/).isVisible(), '冲突不应写入');
    await page.getByRole('button', { name: '生成新版本' }).click();
    await page.getByRole('button', { name: '模拟确认并应用' }).click();
    assert(await page.getByText('版本 3 已应用（模拟）。真实项目仍需运行和检查。').isVisible(), '应用结果丢失');
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.screenshot({ path: `output/playwright/new-design-${index + 1}.png`, fullPage: true });
    await page.setViewportSize({ width: 390, height: 844 });
    assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), '设计页窄屏溢出');
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.screenshot({ path: `output/playwright/new-design-${index + 1}-mobile.png`, fullPage: true });
    await page.setViewportSize({ width: 1440, height: 1000 });
    await switcher.selectOption('');
    await page.getByRole('textbox', { name: '项目空间名称' }).fill('品牌官网');
    await page.getByRole('button', { name: '创建项目空间', exact: true }).click();
    assert(await switcher.inputValue() !== id, '同名项目应有不同编号');
    await page.getByRole('combobox', { name: '模拟检测结果' }).selectOption('missing');
    await page.getByRole('button', { name: '进入设计体系' }).click();
    assert(await page.getByRole('radio', { name: /沿用项目现有主题/ }).isDisabled(), '无主题不可沿用');
    await page.getByRole('button', { name: '生成待应用版本' }).click();
    await switcher.selectOption(id);
    await page.getByRole('button', { name: '进入设计体系' }).click();
    assert(await page.getByRole('slider', { name: '圆角阶梯' }).inputValue() === '16', '项目草稿串联或丢失');
    assert(await page.getByText('版本 3 已应用（模拟）。真实项目仍需运行和检查。').isVisible(), '项目版本未保留');
    await page.getByRole('button', { name: '主页', exact: true }).first().click();
    await page.setViewportSize({ width: 390, height: 844 });
    assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), '主页窄屏溢出');
    await page.screenshot({ path: `output/playwright/new-home-${index + 1}-mobile.png`, fullPage: true });
    await page.setViewportSize({ width: 1440, height: 1000 });
    results.push(`${name}：创建、初始化、过期、映射、版本、冲突、应用、无主题、项目隔离与窄屏通过`);
  }
  assert(errors.length === 0, errors.join('\n'));
  await page.getByRole('button', { name: '逐步引导', exact: true }).click();
  return { results, errors };
}
